rss.channel:
{{ .Site.Title }}
{{ .Site.BaseURL }}
{{ .Site.Params.description }}
{{ .Site.LanguageCode }}

{{ $pages := .Pages }}
{{ if .IsHome }}{{ $pages = where .Site.RegularPages "Section" "posts" }}{{ end }}
{{ range first 20 $pages }}


  {{ .Title }}
  {{ .Permalink }}
  {{ .Permalink }}
  {{ .Date.Format "Mon, 02 Jan 2006 15:04:05 -0700" }}
  {{ .Site.Params.author }}
  {{ with .Params.tags }}{{ range . }}
  {{ . }}
  {{ end }}{{ end }}
  {{ printf "%s" (.Content | safeHTML) | safeHTML }}

{{ end }}
